import { Agent } from "../../game";
import { Team } from "../../../types";

const BAR_WIDTH = 44;
const BAR_HEIGHT = 6;
const BAR_PADDING = 3;

export const BarPainter = {

    drawUnitBars(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, isSelected: boolean) {
        const hasMp = agent.maxMp > 0;

        const contentW = BAR_WIDTH;
        const hpHeight = BAR_HEIGHT;
        const mpHeight = hasMp ? 3 : 0;
        const gap = hasMp ? 2 : 0;

        const contentH = hpHeight + gap + mpHeight;
        const totalW = contentW + BAR_PADDING * 2;
        const totalH = contentH + BAR_PADDING * 2;

        const startX = x - totalW / 2;
        const startY = y - 5; 

        // Container
        ctx.save();
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(startX, startY, totalW, totalH, 6);
        else ctx.rect(startX, startY, totalW, totalH);

        // Dark Glass BG
        ctx.fillStyle = 'rgba(2, 6, 23, 0.85)'; 
        ctx.fill();

        // Team-colored Border Highlight
        const teamBorder = agent.team === Team.BLUE ? '#3b82f6' : '#ef4444';
        ctx.lineWidth = 1;
        ctx.strokeStyle = isSelected ? teamBorder : 'rgba(255, 255, 255, 0.2)';
        ctx.stroke();

        if (isSelected) {
            ctx.shadowColor = teamBorder;
            ctx.shadowBlur = 10;
            ctx.stroke();
            ctx.shadowBlur = 0;
        }
        ctx.restore();

        const barX = startX + BAR_PADDING;
        const barY = startY + BAR_PADDING;

        // HP Bar - Faction Colored
        const hpPct = Math.max(0, agent.hp / agent.maxHp);

        // Calculate Shield Pct (Relative to Max HP)
        const shieldPct = Math.max(0, agent.shield / agent.maxHp);

        let hpTop, hpBot, hpGlow;

        if (agent.team === Team.BLUE) {
            // IMPERIAL CYAN/BLUE
            hpTop = '#22d3ee';
            hpBot = '#0284c7';
            hpGlow = 'rgba(6, 182, 212, 0.5)';
        } else {
            // COVENANT RED/ORANGE
            hpTop = '#f87171';
            hpBot = '#dc2626';
            hpGlow = 'rgba(220, 38, 38, 0.5)';
        }

        // 1. Draw Empty Slot Background (Dark Grey)
        ctx.fillStyle = '#1e293b';
        ctx.fillRect(barX, barY, contentW, hpHeight);

        // 2. Draw Base HP
        this.drawFluidBar(ctx, barX, barY, contentW, hpHeight, hpPct, hpTop, hpBot, hpGlow);

        // 3. Draw Shield Overlay (Fix: Ensure visibility)
        if (shieldPct > 0) {
            // Shield starts where HP ends
            const shieldStartX = barX + (contentW * hpPct);

            // Allow shield to visually overlay the empty part of HP bar, and even extend slightly
            // Max visual width is limited to remaining bar space + 20% overflow
            const remainingPct = 1.0 - hpPct;
            const drawShieldPct = Math.min(shieldPct, remainingPct + 0.3); 
            const shieldW = contentW * drawShieldPct;

            if (shieldW > 0.5) {
                // Shield Colors (White/Silver/Energy) - High Contrast
                const shieldTop = '#ffffff';
                const shieldBot = '#cbd5e1';

                ctx.save();
                ctx.beginPath();
                // No rounding on left side to connect with HP
                ctx.rect(shieldStartX, barY, shieldW, hpHeight);

                const grad = ctx.createLinearGradient(shieldStartX, barY, shieldStartX, barY + hpHeight);
                grad.addColorStop(0, shieldTop);
                grad.addColorStop(1, shieldBot);
                ctx.fillStyle = grad;
                ctx.shadowColor = '#fff';
                ctx.shadowBlur = 5;
                ctx.fill();
                ctx.shadowBlur = 0;

                // Shield Seam
                ctx.beginPath();
                ctx.moveTo(shieldStartX, barY);
                ctx.lineTo(shieldStartX, barY + hpHeight);
                ctx.strokeStyle = 'rgba(0,0,0,0.5)';
                ctx.lineWidth = 1;
                ctx.stroke();

                // Over-shield indicator (White outline if shield is huge)
                if (agent.shield > agent.maxHp * 0.5) {
                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 1;
                    ctx.strokeRect(barX - 1, barY - 1, contentW + 2, hpHeight + 2);
                }
                ctx.restore();
            }
        }

        // MP Bar - Always Blue/Purple
        if (hasMp) {
            const mpPct = Math.max(0, agent.mp / agent.maxMp);
            const mpY = barY + hpHeight + gap;
            // Draw empty MP background
            ctx.fillStyle = '#1e293b';
            ctx.fillRect(barX, mpY, contentW, mpHeight);

            this.drawFluidBar(ctx, barX, mpY, contentW, mpHeight, mpPct, '#a78bfa', '#7c3aed', 'rgba(139, 92, 246, 0.4)');
        }
    },

    drawFluidBar(ctx: CanvasRenderingContext2D, bx: number, by: number, bw: number, bh: number, pct: number, colTop: string, colBot: string, glow: string) {
        if (pct <= 0.01) return;
        const fillW = Math.max(1, bw * pct); 

        ctx.save();
        ctx.beginPath();
        // Slightly rounded corners
        if (ctx.roundRect) ctx.roundRect(bx, by, fillW, bh, 1);
        else ctx.rect(bx, by, fillW, bh);

        const grad = ctx.createLinearGradient(bx, by, bx, by + bh);
        grad.addColorStop(0, colTop);
        grad.addColorStop(1, colBot);
        ctx.fillStyle = grad;

        ctx.shadowColor = glow;
        ctx.shadowBlur = 6;
        ctx.fill();
        ctx.shadowBlur = 0;

        // Gloss highlight
        ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(bx, by, fillW, bh * 0.4, 1);
        else ctx.rect(bx, by, fillW, bh * 0.4);
        ctx.fill();

        ctx.restore();
    }
};

import { GroundHazard } from "../../../../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../../../constants";
import { HAZARD_VISUALS } from "../../../../../data/vfx/hazard_visuals";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { SurfacePainter } from "../../../graphics/painters/SurfacePainter";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";
import { VisualMath } from "../../../math/VisualMath";

export const HazardPainter = {
    draw(ctx: CanvasRenderingContext2D, x: number, y: number, hazard: GroundHazard, globalTime: number) {
        const def = HAZARD_VISUALS[hazard.type] || HAZARD_VISUALS['GENERIC'];
        // Smooth fade out at end of duration
        let fade = hazard.duration < 0.8 ? hazard.duration / 0.8 : 1.0;

        ctx.save();
        ctx.globalAlpha = fade;
        const drawY = VisualMath.applyLayerBias(y, 'HAZARD');

        if (def.type === 'FOG') {
            const texture = VFXFactory.getTexture('SMOKE', def.primaryColor);
            const size = HEX_SIZE * 3.5; // Slightly larger coverage
            const speed = globalTime * def.speed;

            ctx.save();
            ctx.translate(x, drawY + VisualMath.Z_LAYERS.HAZARD_FOG); 
            ctx.scale(1, ISO_SCALE_Y);

            // Base Layer: Opaque-ish for visibility
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = def.intensity * 0.5; // Increased base opacity
            ctx.drawImage(texture, -size * 0.3, -size * 0.3, size * 0.6, size * 0.6);

            // Swirl Layer 1
            ctx.globalCompositeOperation = (hazard.type === 'POISON') ? 'source-over' : 'screen'; 
            ctx.save(); 
            ctx.rotate(speed * 0.12); 
            ctx.globalAlpha = def.intensity * 0.4; 
            ctx.drawImage(texture, -size/2, -size/2, size, size); 
            ctx.restore();

            // Swirl Layer 2
            ctx.save(); 
            ctx.rotate(-speed * 0.08 + 2.0); 
            ctx.scale(0.9, 0.9); 
            ctx.globalAlpha = def.intensity * 0.3; 
            ctx.drawImage(texture, -size/2, -size/2, size, size); 
            ctx.restore();

            ctx.restore();
        }
        else if (def.type === 'LIQUID') {
            const speed = globalTime * def.speed;
            const intensity = def.intensity * (0.85 + Math.sin(speed * 0.8) * 0.15);
            const liquidY = drawY + VisualMath.Z_LAYERS.LIQUID_OFFSET;

            // Draw liquid with high opacity
            SurfacePainter.drawLiquid(ctx, x, liquidY, def.primaryColor, speed, Math.min(1.0, intensity * 1.2));
            if (def.cracks) SurfacePainter.drawCracks(ctx, x, liquidY, def.secondaryColor, intensity);

            if (hazard.type === 'FIRE') {
                const flameTex = VFXFactory.getTexture('SMOKE', '#fca5a5');
                const rise = (globalTime * 50) % 30;
                ctx.save();
                ctx.translate(x, liquidY - 10 - rise);
                ctx.globalCompositeOperation = 'screen'; 
                ctx.globalAlpha = (1 - rise/30) * intensity;
                ctx.scale(0.8, 1.2); // Elongate flames
                ctx.drawImage(flameTex, -20, -60, 40, 60);
                ctx.restore();
            }
        }
        else if (def.type === 'CRYSTAL') {
            if (def.extrude) VolumePainter.drawExtrusion(ctx, x, drawY, HEX_SIZE * 0.8, 8, def.primaryColor, 0.7);
            ctx.save();
            ctx.translate(x, drawY - 5); ctx.scale(1, ISO_SCALE_Y);
            ctx.globalCompositeOperation = 'screen'; ctx.globalAlpha = 0.6;
            ctx.drawImage(VFXFactory.getTexture('ROCK', def.secondaryColor), -15, -15, 30, 30);
            ctx.restore();
        }
        else if (def.type === 'VOID_HOLE') {
            const r = HEX_SIZE * 1.6;
            ctx.save();
            ctx.translate(x, drawY); ctx.scale(1, ISO_SCALE_Y);
            ctx.globalCompositeOperation = 'source-over'; ctx.fillStyle = '#000';
            ctx.beginPath(); ctx.arc(0, 0, r * 0.7, 0, Math.PI*2); ctx.fill();

            ctx.globalCompositeOperation = 'lighter'; 
            ctx.lineWidth = 4; 
            ctx.strokeStyle = def.secondaryColor;
            ctx.shadowColor = def.secondaryColor; 
            ctx.shadowBlur = 20;

            ctx.rotate(globalTime * 3);
            ctx.beginPath();
            for(let i=0; i<3; i++) {
                const ang = i * (Math.PI*2/3); ctx.moveTo(0,0);
                ctx.quadraticCurveTo(Math.cos(ang)*r, Math.sin(ang)*r, Math.cos(ang+1)*r, Math.sin(ang+1)*r);
            }
            ctx.stroke();
            ctx.restore();
        }
        ctx.restore();
    }
};

import { Agent, GameEngine } from "../../game";
import { AnimState } from "../../../types";
import { HexUtils } from "../../utils";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";

export class ControlSystem {
    // VFX throttling map
    private vfxTimers = new Map<string, number>();

    public update(agent: Agent, dt: number, engine: GameEngine) {
        // 0. AI Tick Update (System-wide clock for the agent)
        if (agent.aiUpdateTimer > 0) {
            agent.aiUpdateTimer -= dt;
        }

        // 1. Diminishing Returns (DR) Decay
        for (const type in agent.drTimers) {
            if (Object.prototype.hasOwnProperty.call(agent.drTimers, type)) {
                agent.drTimers[type] -= dt;
                if (agent.drTimers[type] <= 0) {
                    agent.drStacks[type] = 0;
                    delete agent.drTimers[type];
                }
            }
        }

        // 2. Status Timer Ticks
        if (agent.banishTimer > 0) agent.banishTimer = Math.max(0, agent.banishTimer - dt);
        if (agent.stunTimer > 0) agent.stunTimer = Math.max(0, agent.stunTimer - dt);
        if (agent.silenceTimer > 0) agent.silenceTimer = Math.max(0, agent.silenceTimer - dt);
        if (agent.rootTimer > 0) agent.rootTimer = Math.max(0, agent.rootTimer - dt);
        if (agent.fearTimer > 0) agent.fearTimer = Math.max(0, agent.fearTimer - dt);
        if (agent.blindTimer > 0) agent.blindTimer = Math.max(0, agent.blindTimer - dt);
        if (agent.tauntTimer > 0) {
            agent.tauntTimer = Math.max(0, agent.tauntTimer - dt);
            if (agent.tauntTimer <= 0) agent.tauntTargetId = null;
        }

        // 3. State Resolution & Priority Logic
        if (agent.banishTimer > 0) {
            agent.banished = true;
            agent.isMoving = false;
            agent.path = [];
            this.processStatusVFX(agent, dt, engine); // Early VFX process for banished
            return; 
        } else {
            if (agent.banished) {
                agent.banished = false;
                agent.visualStatus = 'NONE';
                engine.log(agent, 'CC', '放逐結束', null, '重返戰場');
            }
        }

        if (agent.stunTimer > 0) {
            agent.isMoving = false;
            agent.path = [];
            agent.setAnim(AnimState.STUN);
        } else if (agent.visualStatus === 'FROZEN') {
            agent.visualStatus = 'NONE';
        }

        if (agent.fearTimer > 0) {
            // FIX: Fear Logic Jitter
            // 只有在完全停止時 (Idle) 才尋找新路徑，且強制執行完整移動
            if (agent.rootTimer <= 0) {
                // 如果正在移動，不要打斷，讓它跑完
                if (!agent.isMoving) {
                    // 擴大搜索半徑至 3-4 格，模擬長距離驚慌亂跑
                    const range = 4;
                    const center = { q: agent.q, r: agent.r };
                    const candidates = HexUtils.range(center, range).filter(h => {
                        // 排除近身 (Range < 2)，強迫跑遠
                        if (HexUtils.dist(center, h) < 2) return false;
                        return engine.map.isValid(h.q, h.r) && !engine.map.isBlocked(h.q, h.r, engine, agent.id);
                    });

                    if (candidates.length > 0) {
                        // 隨機選一個
                        const targetHex = candidates[Math.floor(Math.random() * candidates.length)];
                        // 強制走到該點，速度 1.5x
                        engine.moveAgentToHex(agent, targetHex, 0, 1.5); 
                    }
                }
            } else {
                // 如果被定身，停止移動
                agent.isMoving = false;
                agent.path = [];
            }
        }

        if (agent.rootTimer > 0) {
            agent.isMoving = false;
            agent.path = [];
        }

        if (!agent.isMoving && agent.castingSkillIdx === -1 && agent.hitFlashTimer <= 0 && agent.hp > 0) {
            if (agent.target) agent.setAnim(AnimState.COMBAT_IDLE);
            else agent.setAnim(AnimState.IDLE);
        }

        // 5. Visual Effects Tick (Loop for all states)
        this.processStatusVFX(agent, dt, engine);
    }

    private processStatusVFX(agent: Agent, dt: number, engine: GameEngine) {
        if (!engine.renderer) return;

        const checkVFX = (key: string, condition: boolean) => {
            if (!condition) return;
            const def = STATUS_VISUALS[key];
            if (!def || !def.particleEffect) return;

            const timerKey = `${agent.id}_${key}`;
            let t = this.vfxTimers.get(timerKey) || 0;
            t -= dt;

            if (t <= 0) {
                t = def.particleInterval || 0.5;
                const h = engine.map.getTerrainHeight(agent.q, agent.r);

                // Lift particles up to chest/head height so they aren't hidden by the body
                // Agent Z is bottom of feet relative to terrain.
                // 45 is roughly center mass.
                const pz = agent.physics.z + 45;

                engine.renderer.vfx.playEffect(
                    def.particleEffect, 
                    agent.px, agent.py, 
                    h + pz
                );
            }
            this.vfxTimers.set(timerKey, t);
        };

        checkVFX('POISON', agent.dotTimer > 0 && agent.dotDmg > 0);
        checkVFX('BURN', agent.dotTimer > 0 && agent.dotDmg > 0); // Explicitly check BURN
        checkVFX('REGEN', agent.hotTimer > 0);
        checkVFX('BANISH', agent.banished);
        checkVFX('STUN', agent.stunTimer > 0);
        checkVFX('SILENCE', agent.silenceTimer > 0);
        checkVFX('FEAR', agent.fearTimer > 0);
        checkVFX('ROOT', agent.rootTimer > 0);
    }
}

import { Agent } from "../../../../game";
import { Team } from "../../../../../types";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";

export const ShieldPainter = {
    /**
     * 繪製包裹單位的能量護盾
     * @param y 單位視覺中心 Y 軸
     */
    draw(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, t: number) {
        if (agent.shield <= 0) return;

        const isBlue = agent.team === Team.BLUE;
        const color = isBlue ? '#60a5fa' : '#ef4444';

        // 護盾強度視覺映射
        const pct = Math.min(1, agent.shield / (agent.maxShield || 100));

        // Increased visibility: Base pulse 0.3 -> 0.5
        const pulse = 0.3 + (pct * 0.4) + Math.sin(t * 5) * 0.1;

        ctx.save();
        ctx.translate(x, y); 

        // 使用 3D 稜柱繪製體積感
        // 向上抬升一半高度以實現垂直居中
        const shieldH = 80;
        const shieldR = 38;

        ctx.globalCompositeOperation = 'screen';
        // 'SOLID' style for better visibility, with adjusted opacity inside painter
        VolumePainter.draw3DPrism(ctx, 0, shieldH/2, shieldR, shieldH, color, pulse, 'GRADIENT_FADE');

        // 邊緣掃描線 (TA 效果) - Enhanced with double scanlines
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2; // Thicker lines

        // Primary Scanline
        ctx.globalAlpha = Math.min(1, pulse * 1.2);
        const scanLineY1 = (t * 120) % shieldH - shieldH/2;
        ctx.beginPath();
        ctx.moveTo(-shieldR * 0.9, scanLineY1);
        ctx.lineTo(shieldR * 0.9, scanLineY1);
        ctx.stroke();

        // Secondary Scanline (Offset, fainter)
        ctx.globalAlpha = Math.min(1, pulse * 0.6);
        const scanLineY2 = ((t * 120 + shieldH * 0.5) % shieldH) - shieldH/2;
        ctx.beginPath();
        ctx.moveTo(-shieldR * 0.7, scanLineY2);
        ctx.lineTo(shieldR * 0.7, scanLineY2);
        ctx.stroke();

        // Shield Top/Bottom Caps for definition
        ctx.globalAlpha = 0.4;
        ctx.lineWidth = 1;
        ctx.strokeStyle = color;
        ctx.beginPath();
        ctx.ellipse(0, -shieldH/2, shieldR, shieldR*0.5, 0, 0, Math.PI*2);
        ctx.stroke();
        ctx.beginPath();
        ctx.ellipse(0, shieldH/2, shieldR, shieldR*0.5, 0, 0, Math.PI*2);
        ctx.stroke();

        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { ISO_SCALE_Y } from "../../../../../constants";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

// 數學規範：CC 地面層偏置量
const CC_GROUND_BIAS = -5;

export const GroundEffectPainter = {
    /**
     * 繪製單位腳下的持續性 CC 特效
     * @param y 單位目前的視覺腳底高度 (含物理 Z)
     */
    draw(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, t: number) {
        // 1. 禁錮效果 (Root / Vines)
        if (agent.rootTimer > 0) {
            const color = '#fbbf24'; 
            ctx.save();
            ctx.translate(x, y + CC_GROUND_BIAS);

            // 幾何脈衝函數
            const pulse = 0.8 + Math.sin(t * 12) * 0.15;
            const r = 24 * pulse;

            // A. 底層能量環 (Vector Hex)
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.8; // Increased from 0.6
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;
            HexGeometry.traceHex(ctx, 0, 0, r, true);
            ctx.stroke();

            // B. 3D 突刺 (幾何模擬)
            ctx.fillStyle = color;
            ctx.globalCompositeOperation = 'source-over';
            const count = 3;
            for(let i=0; i<count; i++) {
                const angle = i * (Math.PI*2/count) + t * 2;
                const sx = Math.cos(angle) * (r * 0.7);
                const sy = Math.sin(angle) * (r * 0.7) * ISO_SCALE_Y;

                ctx.beginPath();
                ctx.moveTo(sx, sy);
                ctx.lineTo(sx, sy - 25); // Taller spikes (20 -> 25)
                ctx.lineTo(sx + 6, sy + 2);
                ctx.fill();
            }
            ctx.restore();
        }

        // 2. 灼燒/DoT 地標 (Burn Ground)
        if (agent.dotTimer > 0 && agent.dotDmg > 0) {
            const color = agent.team === 0 ? '#10b981' : '#ef4444'; // Green for poison (vs Blue), Red for burn (vs Red) default
            // Actually, color should depend on hazard source or effect type, but simplified:
            // Use generic "bad ground" look

            ctx.save();
            ctx.translate(x, y + CC_GROUND_BIAS + 1); 
            ctx.globalCompositeOperation = 'screen'; // Use screen for glow

            const r = 22 + Math.sin(t * 15) * 3; // Larger radius
            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
            grad.addColorStop(0, 'rgba(255, 255, 255, 0.6)'); // Hot center
            grad.addColorStop(0.4, 'rgba(239, 68, 68, 0.6)'); // Red mid
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.scale(1, ISO_SCALE_Y);
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

            // Outer ring
            ctx.strokeStyle = '#ef4444';
            ctx.lineWidth = 1.5;
            ctx.globalAlpha = 0.7;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.stroke();

            ctx.restore();
        }
    }
};

import { Agent } from "../../game";
import { Team } from "../../../types";

const BAR_WIDTH = 44;
const BAR_HEIGHT = 6;
const BAR_PADDING = 3;

export const BarPainter = {

    drawUnitBars(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, isSelected: boolean) {
        const hasMp = agent.maxMp > 0;

        const contentW = BAR_WIDTH;
        const hpHeight = BAR_HEIGHT;
        const mpHeight = hasMp ? 3 : 0;
        const gap = hasMp ? 2 : 0;

        const contentH = hpHeight + gap + mpHeight;
        const totalW = contentW + BAR_PADDING * 2;
        const totalH = contentH + BAR_PADDING * 2;

        const startX = x - totalW / 2;
        const startY = y - 5; 

        // Container
        ctx.save();
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(startX, startY, totalW, totalH, 6);
        else ctx.rect(startX, startY, totalW, totalH);

        // Dark Glass BG
        ctx.fillStyle = 'rgba(2, 6, 23, 0.85)'; 
        ctx.fill();

        // Team-colored Border Highlight
        const teamBorder = agent.team === Team.BLUE ? '#3b82f6' : '#ef4444';
        ctx.lineWidth = 1;
        ctx.strokeStyle = isSelected ? teamBorder : 'rgba(255, 255, 255, 0.2)';
        ctx.stroke();

        if (isSelected) {
            ctx.shadowColor = teamBorder;
            ctx.shadowBlur = 10;
            ctx.stroke();
            ctx.shadowBlur = 0;
        }
        ctx.restore();

        const barX = startX + BAR_PADDING;
        const barY = startY + BAR_PADDING;

        // HP Bar - Faction Colored
        const hpPct = Math.max(0, agent.hp / agent.maxHp);

        // Calculate Shield Pct (Relative to Max HP)
        const shieldPct = Math.max(0, agent.shield / agent.maxHp);

        let hpTop, hpBot, hpGlow;

        if (agent.team === Team.BLUE) {
            // IMPERIAL CYAN/BLUE
            hpTop = '#22d3ee';
            hpBot = '#0284c7';
            hpGlow = 'rgba(6, 182, 212, 0.5)';
        } else {
            // COVENANT RED/ORANGE
            hpTop = '#f87171';
            hpBot = '#dc2626';
            hpGlow = 'rgba(220, 38, 38, 0.5)';
        }

        // 1. Draw Empty Slot Background (Dark Grey)
        ctx.fillStyle = '#1e293b';
        ctx.fillRect(barX, barY, contentW, hpHeight);

        // 2. Draw Base HP
        this.drawFluidBar(ctx, barX, barY, contentW, hpHeight, hpPct, hpTop, hpBot, hpGlow);

        // 3. Draw Shield Overlay (Fix: Ensure visibility)
        if (shieldPct > 0) {
            // Shield starts where HP ends
            const shieldStartX = barX + (contentW * hpPct);

            // Allow shield to visually overlay the empty part of HP bar, and even extend slightly
            // Max visual width is limited to remaining bar space + 20% overflow
            const remainingPct = 1.0 - hpPct;
            const drawShieldPct = Math.min(shieldPct, remainingPct + 0.3); 
            const shieldW = contentW * drawShieldPct;

            if (shieldW > 0.5) {
                // Shield Colors (White/Silver/Energy) - High Contrast
                const shieldTop = '#ffffff';
                const shieldBot = '#cbd5e1';

                ctx.save();
                ctx.beginPath();
                // No rounding on left side to connect with HP
                ctx.rect(shieldStartX, barY, shieldW, hpHeight);

                const grad = ctx.createLinearGradient(shieldStartX, barY, shieldStartX, barY + hpHeight);
                grad.addColorStop(0, shieldTop);
                grad.addColorStop(1, shieldBot);
                ctx.fillStyle = grad;
                ctx.shadowColor = '#fff';
                ctx.shadowBlur = 5;
                ctx.fill();
                ctx.shadowBlur = 0;

                // Shield Seam
                ctx.beginPath();
                ctx.moveTo(shieldStartX, barY);
                ctx.lineTo(shieldStartX, barY + hpHeight);
                ctx.strokeStyle = 'rgba(0,0,0,0.5)';
                ctx.lineWidth = 1;
                ctx.stroke();

                // Over-shield indicator (White outline if shield is huge)
                if (agent.shield > agent.maxHp * 0.5) {
                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 1;
                    ctx.strokeRect(barX - 1, barY - 1, contentW + 2, hpHeight + 2);
                }
                ctx.restore();
            }
        }

        // MP Bar - Always Blue/Purple
        if (hasMp) {
            const mpPct = Math.max(0, agent.mp / agent.maxMp);
            const mpY = barY + hpHeight + gap;
            // Draw empty MP background
            ctx.fillStyle = '#1e293b';
            ctx.fillRect(barX, mpY, contentW, mpHeight);

            this.drawFluidBar(ctx, barX, mpY, contentW, mpHeight, mpPct, '#a78bfa', '#7c3aed', 'rgba(139, 92, 246, 0.4)');
        }
    },

    drawFluidBar(ctx: CanvasRenderingContext2D, bx: number, by: number, bw: number, bh: number, pct: number, colTop: string, colBot: string, glow: string) {
        if (pct <= 0.01) return;
        const fillW = Math.max(1, bw * pct); 

        ctx.save();
        ctx.beginPath();
        // Slightly rounded corners
        if (ctx.roundRect) ctx.roundRect(bx, by, fillW, bh, 1);
        else ctx.rect(bx, by, fillW, bh);

        const grad = ctx.createLinearGradient(bx, by, bx, by + bh);
        grad.addColorStop(0, colTop);
        grad.addColorStop(1, colBot);
        ctx.fillStyle = grad;

        ctx.shadowColor = glow;
        ctx.shadowBlur = 6;
        ctx.fill();
        ctx.shadowBlur = 0;

        // Gloss highlight
        ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(bx, by, fillW, bh * 0.4, 1);
        else ctx.rect(bx, by, fillW, bh * 0.4);
        ctx.fill();

        ctx.restore();
    }
};

import { GroundHazard } from "../../../../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../../../constants";
import { HAZARD_VISUALS } from "../../../../../data/vfx/hazard_visuals";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { SurfacePainter } from "../../../graphics/painters/SurfacePainter";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";
import { VisualMath } from "../../../math/VisualMath";

export const HazardPainter = {
    draw(ctx: CanvasRenderingContext2D, x: number, y: number, hazard: GroundHazard, globalTime: number) {
        const def = HAZARD_VISUALS[hazard.type] || HAZARD_VISUALS['GENERIC'];
        // Smooth fade out at end of duration
        let fade = hazard.duration < 0.8 ? hazard.duration / 0.8 : 1.0;

        ctx.save();
        ctx.globalAlpha = fade;
        const drawY = VisualMath.applyLayerBias(y, 'HAZARD');

        if (def.type === 'FOG') {
            const texture = VFXFactory.getTexture('SMOKE', def.primaryColor);
            const size = HEX_SIZE * 3.5; // Slightly larger coverage
            const speed = globalTime * def.speed;

            ctx.save();
            ctx.translate(x, drawY + VisualMath.Z_LAYERS.HAZARD_FOG); 
            ctx.scale(1, ISO_SCALE_Y);

            // Base Layer: Opaque-ish for visibility
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = def.intensity * 0.5; // Increased base opacity
            ctx.drawImage(texture, -size * 0.3, -size * 0.3, size * 0.6, size * 0.6);

            // Swirl Layer 1
            ctx.globalCompositeOperation = (hazard.type === 'POISON') ? 'source-over' : 'screen'; 
            ctx.save(); 
            ctx.rotate(speed * 0.12); 
            ctx.globalAlpha = def.intensity * 0.4; 
            ctx.drawImage(texture, -size/2, -size/2, size, size); 
            ctx.restore();

            // Swirl Layer 2
            ctx.save(); 
            ctx.rotate(-speed * 0.08 + 2.0); 
            ctx.scale(0.9, 0.9); 
            ctx.globalAlpha = def.intensity * 0.3; 
            ctx.drawImage(texture, -size/2, -size/2, size, size); 
            ctx.restore();

            ctx.restore();
        }
        else if (def.type === 'LIQUID') {
            const speed = globalTime * def.speed;
            const intensity = def.intensity * (0.85 + Math.sin(speed * 0.8) * 0.15);
            const liquidY = drawY + VisualMath.Z_LAYERS.LIQUID_OFFSET;

            // Draw liquid with high opacity
            SurfacePainter.drawLiquid(ctx, x, liquidY, def.primaryColor, speed, Math.min(1.0, intensity * 1.2));
            if (def.cracks) SurfacePainter.drawCracks(ctx, x, liquidY, def.secondaryColor, intensity);

            if (hazard.type === 'FIRE') {
                const flameTex = VFXFactory.getTexture('SMOKE', '#fca5a5');
                const rise = (globalTime * 50) % 30;
                ctx.save();
                ctx.translate(x, liquidY - 10 - rise);
                ctx.globalCompositeOperation = 'screen'; 
                ctx.globalAlpha = (1 - rise/30) * intensity;
                ctx.scale(0.8, 1.2); // Elongate flames
                ctx.drawImage(flameTex, -20, -60, 40, 60);
                ctx.restore();
            }
        }
        else if (def.type === 'CRYSTAL') {
            if (def.extrude) VolumePainter.drawExtrusion(ctx, x, drawY, HEX_SIZE * 0.8, 8, def.primaryColor, 0.7);
            ctx.save();
            ctx.translate(x, drawY - 5); ctx.scale(1, ISO_SCALE_Y);
            ctx.globalCompositeOperation = 'screen'; ctx.globalAlpha = 0.6;
            ctx.drawImage(VFXFactory.getTexture('ROCK', def.secondaryColor), -15, -15, 30, 30);
            ctx.restore();
        }
        else if (def.type === 'VOID_HOLE') {
            const r = HEX_SIZE * 1.6;
            ctx.save();
            ctx.translate(x, drawY); ctx.scale(1, ISO_SCALE_Y);
            ctx.globalCompositeOperation = 'source-over'; ctx.fillStyle = '#000';
            ctx.beginPath(); ctx.arc(0, 0, r * 0.7, 0, Math.PI*2); ctx.fill();

            ctx.globalCompositeOperation = 'lighter'; 
            ctx.lineWidth = 4; 
            ctx.strokeStyle = def.secondaryColor;
            ctx.shadowColor = def.secondaryColor; 
            ctx.shadowBlur = 20;

            ctx.rotate(globalTime * 3);
            ctx.beginPath();
            for(let i=0; i<3; i++) {
                const ang = i * (Math.PI*2/3); ctx.moveTo(0,0);
                ctx.quadraticCurveTo(Math.cos(ang)*r, Math.sin(ang)*r, Math.cos(ang+1)*r, Math.sin(ang+1)*r);
            }
            ctx.stroke();
            ctx.restore();
        }
        ctx.restore();
    }
};

import { Agent, GameEngine } from "../../game";
import { AnimState } from "../../../types";
import { HexUtils } from "../../utils";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";

export class ControlSystem {
    // VFX throttling map
    private vfxTimers = new Map<string, number>();

    public update(agent: Agent, dt: number, engine: GameEngine) {
        // 0. AI Tick Update (System-wide clock for the agent)
        if (agent.aiUpdateTimer > 0) {
            agent.aiUpdateTimer -= dt;
        }

        // 1. Diminishing Returns (DR) Decay
        for (const type in agent.drTimers) {
            if (Object.prototype.hasOwnProperty.call(agent.drTimers, type)) {
                agent.drTimers[type] -= dt;
                if (agent.drTimers[type] <= 0) {
                    agent.drStacks[type] = 0;
                    delete agent.drTimers[type];
                }
            }
        }

        // 2. Status Timer Ticks
        if (agent.banishTimer > 0) agent.banishTimer = Math.max(0, agent.banishTimer - dt);
        if (agent.stunTimer > 0) agent.stunTimer = Math.max(0, agent.stunTimer - dt);
        if (agent.silenceTimer > 0) agent.silenceTimer = Math.max(0, agent.silenceTimer - dt);
        if (agent.rootTimer > 0) agent.rootTimer = Math.max(0, agent.rootTimer - dt);
        if (agent.fearTimer > 0) agent.fearTimer = Math.max(0, agent.fearTimer - dt);
        if (agent.blindTimer > 0) agent.blindTimer = Math.max(0, agent.blindTimer - dt);
        if (agent.tauntTimer > 0) {
            agent.tauntTimer = Math.max(0, agent.tauntTimer - dt);
            if (agent.tauntTimer <= 0) agent.tauntTargetId = null;
        }

        // 3. State Resolution & Priority Logic
        if (agent.banishTimer > 0) {
            agent.banished = true;
            agent.isMoving = false;
            agent.path = [];
            this.processStatusVFX(agent, dt, engine); // Early VFX process for banished
            return; 
        } else {
            if (agent.banished) {
                agent.banished = false;
                agent.visualStatus = 'NONE';
                engine.log(agent, 'CC', '放逐結束', null, '重返戰場');
            }
        }

        if (agent.stunTimer > 0) {
            agent.isMoving = false;
            agent.path = [];
            agent.setAnim(AnimState.STUN);
        } else if (agent.visualStatus === 'FROZEN') {
            agent.visualStatus = 'NONE';
        }

        if (agent.fearTimer > 0) {
            // FIX: Fear Logic Jitter
            // 只有在完全停止時 (Idle) 才尋找新路徑，且強制執行完整移動
            if (agent.rootTimer <= 0) {
                // 如果正在移動，不要打斷，讓它跑完
                if (!agent.isMoving) {
                    // 擴大搜索半徑至 3-4 格，模擬長距離驚慌亂跑
                    const range = 4;
                    const center = { q: agent.q, r: agent.r };
                    const candidates = HexUtils.range(center, range).filter(h => {
                        // 排除近身 (Range < 2)，強迫跑遠
                        if (HexUtils.dist(center, h) < 2) return false;
                        return engine.map.isValid(h.q, h.r) && !engine.map.isBlocked(h.q, h.r, engine, agent.id);
                    });

                    if (candidates.length > 0) {
                        // 隨機選一個
                        const targetHex = candidates[Math.floor(Math.random() * candidates.length)];
                        // 強制走到該點，速度 1.5x
                        engine.moveAgentToHex(agent, targetHex, 0, 1.5); 
                    }
                }
            } else {
                // 如果被定身，停止移動
                agent.isMoving = false;
                agent.path = [];
            }
        }

        if (agent.rootTimer > 0) {
            agent.isMoving = false;
            agent.path = [];
        }

        if (!agent.isMoving && agent.castingSkillIdx === -1 && agent.hitFlashTimer <= 0 && agent.hp > 0) {
            if (agent.target) agent.setAnim(AnimState.COMBAT_IDLE);
            else agent.setAnim(AnimState.IDLE);
        }

        // 5. Visual Effects Tick (Loop for all states)
        this.processStatusVFX(agent, dt, engine);
    }

    private processStatusVFX(agent: Agent, dt: number, engine: GameEngine) {
        if (!engine.renderer) return;

        const checkVFX = (key: string, condition: boolean) => {
            if (!condition) return;
            const def = STATUS_VISUALS[key];
            if (!def || !def.particleEffect) return;

            const timerKey = `${agent.id}_${key}`;
            let t = this.vfxTimers.get(timerKey) || 0;
            t -= dt;

            if (t <= 0) {
                t = def.particleInterval || 0.5;
                const h = engine.map.getTerrainHeight(agent.q, agent.r);

                // Lift particles up to chest/head height so they aren't hidden by the body
                // Agent Z is bottom of feet relative to terrain.
                // 45 is roughly center mass.
                const pz = agent.physics.z + 45;

                engine.renderer.vfx.playEffect(
                    def.particleEffect, 
                    agent.px, agent.py, 
                    h + pz
                );
            }
            this.vfxTimers.set(timerKey, t);
        };

        checkVFX('POISON', agent.dotTimer > 0 && agent.dotDmg > 0);
        checkVFX('BURN', agent.dotTimer > 0 && agent.dotDmg > 0); // Explicitly check BURN
        checkVFX('REGEN', agent.hotTimer > 0);
        checkVFX('BANISH', agent.banished);
        checkVFX('STUN', agent.stunTimer > 0);
        checkVFX('SILENCE', agent.silenceTimer > 0);
        checkVFX('FEAR', agent.fearTimer > 0);
        checkVFX('ROOT', agent.rootTimer > 0);
    }
}

import { Agent } from "../../../../game";
import { Team } from "../../../../../types";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";

export const ShieldPainter = {
    /**
     * 繪製包裹單位的能量護盾
     * @param y 單位視覺中心 Y 軸
     */
    draw(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, t: number) {
        if (agent.shield <= 0) return;

        const isBlue = agent.team === Team.BLUE;
        const color = isBlue ? '#60a5fa' : '#ef4444';

        // 護盾強度視覺映射
        const pct = Math.min(1, agent.shield / (agent.maxShield || 100));

        // Increased visibility: Base pulse 0.3 -> 0.5
        const pulse = 0.3 + (pct * 0.4) + Math.sin(t * 5) * 0.1;

        ctx.save();
        ctx.translate(x, y); 

        // 使用 3D 稜柱繪製體積感
        // 向上抬升一半高度以實現垂直居中
        const shieldH = 80;
        const shieldR = 38;

        ctx.globalCompositeOperation = 'screen';
        // 'SOLID' style for better visibility, with adjusted opacity inside painter
        VolumePainter.draw3DPrism(ctx, 0, shieldH/2, shieldR, shieldH, color, pulse, 'GRADIENT_FADE');

        // 邊緣掃描線 (TA 效果) - Enhanced with double scanlines
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2; // Thicker lines

        // Primary Scanline
        ctx.globalAlpha = Math.min(1, pulse * 1.2);
        const scanLineY1 = (t * 120) % shieldH - shieldH/2;
        ctx.beginPath();
        ctx.moveTo(-shieldR * 0.9, scanLineY1);
        ctx.lineTo(shieldR * 0.9, scanLineY1);
        ctx.stroke();

        // Secondary Scanline (Offset, fainter)
        ctx.globalAlpha = Math.min(1, pulse * 0.6);
        const scanLineY2 = ((t * 120 + shieldH * 0.5) % shieldH) - shieldH/2;
        ctx.beginPath();
        ctx.moveTo(-shieldR * 0.7, scanLineY2);
        ctx.lineTo(shieldR * 0.7, scanLineY2);
        ctx.stroke();

        // Shield Top/Bottom Caps for definition
        ctx.globalAlpha = 0.4;
        ctx.lineWidth = 1;
        ctx.strokeStyle = color;
        ctx.beginPath();
        ctx.ellipse(0, -shieldH/2, shieldR, shieldR*0.5, 0, 0, Math.PI*2);
        ctx.stroke();
        ctx.beginPath();
        ctx.ellipse(0, shieldH/2, shieldR, shieldR*0.5, 0, 0, Math.PI*2);
        ctx.stroke();

        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { ISO_SCALE_Y } from "../../../../../constants";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

// 數學規範：CC 地面層偏置量
const CC_GROUND_BIAS = -5;

export const GroundEffectPainter = {
    /**
     * 繪製單位腳下的持續性 CC 特效
     * @param y 單位目前的視覺腳底高度 (含物理 Z)
     */
    draw(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, t: number) {
        // 1. 禁錮效果 (Root / Vines)
        if (agent.rootTimer > 0) {
            const color = '#fbbf24'; 
            ctx.save();
            ctx.translate(x, y + CC_GROUND_BIAS);

            // 幾何脈衝函數
            const pulse = 0.8 + Math.sin(t * 12) * 0.15;
            const r = 24 * pulse;

            // A. 底層能量環 (Vector Hex)
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.8; // Increased from 0.6
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;
            HexGeometry.traceHex(ctx, 0, 0, r, true);
            ctx.stroke();

            // B. 3D 突刺 (幾何模擬)
            ctx.fillStyle = color;
            ctx.globalCompositeOperation = 'source-over';
            const count = 3;
            for(let i=0; i<count; i++) {
                const angle = i * (Math.PI*2/count) + t * 2;
                const sx = Math.cos(angle) * (r * 0.7);
                const sy = Math.sin(angle) * (r * 0.7) * ISO_SCALE_Y;

                ctx.beginPath();
                ctx.moveTo(sx, sy);
                ctx.lineTo(sx, sy - 25); // Taller spikes (20 -> 25)
                ctx.lineTo(sx + 6, sy + 2);
                ctx.fill();
            }
            ctx.restore();
        }

        // 2. 灼燒/DoT 地標 (Burn Ground)
        if (agent.dotTimer > 0 && agent.dotDmg > 0) {
            const color = agent.team === 0 ? '#10b981' : '#ef4444'; // Green for poison (vs Blue), Red for burn (vs Red) default
            // Actually, color should depend on hazard source or effect type, but simplified:
            // Use generic "bad ground" look

            ctx.save();
            ctx.translate(x, y + CC_GROUND_BIAS + 1); 
            ctx.globalCompositeOperation = 'screen'; // Use screen for glow

            const r = 22 + Math.sin(t * 15) * 3; // Larger radius
            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
            grad.addColorStop(0, 'rgba(255, 255, 255, 0.6)'); // Hot center
            grad.addColorStop(0.4, 'rgba(239, 68, 68, 0.6)'); // Red mid
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.scale(1, ISO_SCALE_Y);
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

            // Outer ring
            ctx.strokeStyle = '#ef4444';
            ctx.lineWidth = 1.5;
            ctx.globalAlpha = 0.7;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.stroke();

            ctx.restore();
        }
    }
};

import { GroundHazard } from "../../../../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../../../constants";
import { HAZARD_VISUALS } from "../../../../../data/vfx/hazard_visuals";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { SurfacePainter } from "../../../graphics/painters/SurfacePainter";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";
import { VisualMath } from "../../../math/VisualMath";

export const HazardPainter = {
    draw(ctx: CanvasRenderingContext2D, x: number, y: number, hazard: GroundHazard, globalTime: number) {
        const def = HAZARD_VISUALS[hazard.type] || HAZARD_VISUALS['GENERIC'];
        // Smooth fade out at end of duration
        let fade = hazard.duration < 0.8 ? hazard.duration / 0.8 : 1.0;

        ctx.save();
        ctx.globalAlpha = fade;
        const drawY = VisualMath.applyLayerBias(y, 'HAZARD');

        if (def.type === 'FOG') {
            const texture = VFXFactory.getTexture('SMOKE', def.primaryColor);
            const speed = globalTime * def.speed;

            // VOLUMETRIC STACKING (3 Layers)
            // Draw multiple layers at different Y offsets to simulate 3D volume
            const layers = 3;
            const baseSize = HEX_SIZE * 3.5;

            for(let i = 0; i < layers; i++) {
                const layerProgress = i / (layers - 1); // 0.0 to 1.0

                // Higher layers are drawn "higher" (smaller Y in screen space)
                // -25px total height variance
                const layerY = drawY - (i * 12); 

                // Parallax scale: Top layers slightly larger and more transparent
                const scale = 1.0 + (i * 0.1) + Math.sin(speed + i) * 0.05;
                const size = baseSize * scale;

                ctx.save();
                ctx.translate(x, layerY + VisualMath.Z_LAYERS.HAZARD_FOG);
                ctx.scale(1, ISO_SCALE_Y);

                // Rotation variance per layer creates depth
                const rotation = (i % 2 === 0 ? 1 : -1) * (speed * (0.1 + i * 0.05)) + i;
                ctx.rotate(rotation);

                if (i === 0) {
                    // Base Layer: Darker, Grounded
                    ctx.globalCompositeOperation = 'source-over';
                    ctx.globalAlpha = def.intensity * 0.6 * fade;
                } else if (i === 1) {
                    // Mid Layer: Body
                    ctx.globalCompositeOperation = 'source-over';
                    ctx.globalAlpha = def.intensity * 0.4 * fade;
                } else {
                    // Top Layer: Highlights/Wisps
                    ctx.globalCompositeOperation = 'screen';
                    ctx.globalAlpha = def.intensity * 0.3 * fade;
                }

                ctx.drawImage(texture, -size/2, -size/2, size, size);
                ctx.restore();
            }
        }
        else if (def.type === 'LIQUID') {
            const speed = globalTime * def.speed;
            const intensity = def.intensity * (0.85 + Math.sin(speed * 0.8) * 0.15);
            const liquidY = drawY + VisualMath.Z_LAYERS.LIQUID_OFFSET;

            // Draw liquid with high opacity
            SurfacePainter.drawLiquid(ctx, x, liquidY, def.primaryColor, speed, Math.min(1.0, intensity * 1.2));
            if (def.cracks) SurfacePainter.drawCracks(ctx, x, liquidY, def.secondaryColor, intensity);

            if (hazard.type === 'FIRE') {
                const flameTex = VFXFactory.getTexture('SMOKE', '#fca5a5');
                const rise = (globalTime * 50) % 30;
                ctx.save();
                ctx.translate(x, liquidY - 10 - rise);
                ctx.globalCompositeOperation = 'screen'; 
                ctx.globalAlpha = (1 - rise/30) * intensity;
                ctx.scale(0.8, 1.2); // Elongate flames
                ctx.drawImage(flameTex, -20, -60, 40, 60);
                ctx.restore();
            }
        }
        else if (def.type === 'CRYSTAL') {
            if (def.extrude) VolumePainter.drawExtrusion(ctx, x, drawY, HEX_SIZE * 0.8, 8, def.primaryColor, 0.7);
            ctx.save();
            ctx.translate(x, drawY - 5); ctx.scale(1, ISO_SCALE_Y);
            ctx.globalCompositeOperation = 'screen'; ctx.globalAlpha = 0.6;
            ctx.drawImage(VFXFactory.getTexture('ROCK', def.secondaryColor), -15, -15, 30, 30);
            ctx.restore();
        }
        else if (def.type === 'VOID_HOLE') {
            const r = HEX_SIZE * 1.6;
            ctx.save();
            ctx.translate(x, drawY); ctx.scale(1, ISO_SCALE_Y);
            ctx.globalCompositeOperation = 'source-over'; ctx.fillStyle = '#000';
            ctx.beginPath(); ctx.arc(0, 0, r * 0.7, 0, Math.PI*2); ctx.fill();

            ctx.globalCompositeOperation = 'lighter'; 
            ctx.lineWidth = 4; 
            ctx.strokeStyle = def.secondaryColor;
            ctx.shadowColor = def.secondaryColor; 
            ctx.shadowBlur = 20;

            ctx.rotate(globalTime * 3);
            ctx.beginPath();
            for(let i=0; i<3; i++) {
                const ang = i * (Math.PI*2/3); ctx.moveTo(0,0);
                ctx.quadraticCurveTo(Math.cos(ang)*r, Math.sin(ang)*r, Math.cos(ang+1)*r, Math.sin(ang+1)*r);
            }
            ctx.stroke();
            ctx.restore();
        }
        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { ISO_SCALE_Y } from "../../../../../constants";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

// 數學規範：CC 地面層偏置量
const CC_GROUND_BIAS = -5;

export const GroundEffectPainter = {
    /**
     * 繪製單位身上的持續性 CC 特效 (地面 -> 身體)
     * @param y 單位目前的視覺腳底高度 (含物理 Z)
     */
    draw(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, t: number) {
        const groundY = y + CC_GROUND_BIAS;

        // 1. 禁錮效果 (Root / Vines)
        if (agent.rootTimer > 0) {
            const color = '#fbbf24'; 
            ctx.save();
            ctx.translate(x, groundY);

            const pulse = 0.8 + Math.sin(t * 12) * 0.15;
            const r = 24 * pulse;

            // A. 底層能量環
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.8;
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;
            HexGeometry.traceHex(ctx, 0, 0, r, true);
            ctx.stroke();

            // B. 3D 突刺 (幾何模擬)
            ctx.fillStyle = color;
            ctx.globalCompositeOperation = 'source-over';
            const count = 3;
            for(let i=0; i<count; i++) {
                const angle = i * (Math.PI*2/count) + t * 2;
                const sx = Math.cos(angle) * (r * 0.7);
                const sy = Math.sin(angle) * (r * 0.7) * ISO_SCALE_Y;

                ctx.beginPath();
                ctx.moveTo(sx, sy);
                ctx.lineTo(sx, sy - 25); 
                ctx.lineTo(sx + 6, sy + 2);
                ctx.fill();
            }
            ctx.restore();
        }

        // 2. 持續傷害 (DoT) - 顯眼的上升氣流
        if (agent.dotTimer > 0 && agent.dotDmg > 0) {
            // Determine color based on hazard guessing (Green for generic/poison, Red for fire)
            // Since we don't store damage type on agent perfectly, we guess:
            // But we can default to a sickly green/purple for poison, or red for burn.
            // Let's make it distinct based on team? No, Poison is Green.
            const color = '#a3e635'; // Lime Green default
            const secondary = '#4d7c0f';

            ctx.save();
            ctx.translate(x, groundY);

            // Floor Puddle
            ctx.globalCompositeOperation = 'source-over';
            ctx.fillStyle = secondary;
            ctx.globalAlpha = 0.6;
            ctx.beginPath(); 
            ctx.ellipse(0, 0, 20, 10, 0, 0, Math.PI*2); 
            ctx.fill();

            // Rising Fumes (Vertical Lines around body)
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.lineCap = 'round';
            ctx.globalCompositeOperation = 'screen';

            const strands = 4;
            const height = 60;

            for(let i=0; i<strands; i++) {
                const offset = i * (Math.PI * 2 / strands);
                const loopT = (t * 2 + offset) % 1; // 0 to 1
                const curH = loopT * height;
                const fade = Math.sin(loopT * Math.PI); // Fade in/out

                const wave = Math.sin(t * 5 + curH * 0.1) * 5;
                const rx = Math.cos(offset) * 15 + wave;
                const ry = Math.sin(offset) * 15 * ISO_SCALE_Y;

                ctx.globalAlpha = fade;
                ctx.beginPath();
                ctx.moveTo(rx, ry - curH);
                ctx.lineTo(rx, ry - curH - 15); // Length of fume
                ctx.stroke();
            }
            ctx.restore();
        }

        // 3. 持續恢復 (HoT) - 上升十字/光點
        if (agent.hotTimer > 0) {
            const color = '#86efac'; // Bright Green/Mint

            ctx.save();
            ctx.translate(x, groundY);

            // Floor Glow
            ctx.fillStyle = color;
            ctx.globalAlpha = 0.3;
            ctx.globalCompositeOperation = 'screen';
            ctx.beginPath(); ctx.ellipse(0, 0, 20, 10, 0, 0, Math.PI*2); ctx.fill();

            // Spiraling Energy
            const particles = 3;
            const height = 70;

            for(let i=0; i<particles; i++) {
                const offset = i * (Math.PI * 2 / particles);
                const loopT = (t * 1.5 + offset) % 1;
                const curH = loopT * height;
                const fade = 1.0 - Math.pow(Math.abs(loopT - 0.5) * 2, 2); // Smooth bell curve fade

                const angle = t * 4 + curH * 0.1;
                const radius = 20 * (1 - loopT * 0.5); // Taper in

                const px = Math.cos(angle) * radius;
                const py = Math.sin(angle) * radius * ISO_SCALE_Y;

                ctx.globalAlpha = fade;
                ctx.fillStyle = color;

                // Draw Plus Sign or Dot
                ctx.save();
                ctx.translate(px, py - curH);
                ctx.fillRect(-2, -6, 4, 12);
                ctx.fillRect(-6, -2, 12, 4);
                ctx.restore();
            }
            ctx.restore();
        }
    }
};

import { GameEngine, Agent } from "../game";
import { HexUtils } from "../utils";
import { Point } from "../../types";

export class DirectorSystem {
    // Dynamic Zoom Baselines (Calculated based on Aspect Ratio)
    private idleZoom = 0.9;
    private combatZoom = 1.15;
    private ultZoom = 1.45;

    // Controls
    public enabled: boolean = true;

    // State
    private currentFocusPoint: Point = { x: 0, y: 0 };
    private hasInitialized: boolean = false;
    private lastCentroidX: number = 0;
    private lastCentroidY: number = 0;
    private lastAspectRatio: number = 0;

    public reset(engine: GameEngine) {
        const ds = engine.state.director;
        ds.targetId = null;
        ds.focusTimer = 0;
        ds.priorityTimer = 0;
        this.hasInitialized = false;
        this.enabled = true;
    }

    public forceFocus(engine: GameEngine, id: string, duration: number = 2.0) {
        const ds = engine.state.director;
        ds.targetId = id;
        ds.priorityTimer = duration; 
        ds.focusTimer = duration;
    }

    public update(engine: GameEngine, dt: number) {
        if (!this.enabled) return;

        // 0. Update Zoom Logic based on Canvas Aspect Ratio
        // This fixes the "Not scaling up" issue in Fullscreen
        if (engine.renderer && engine.renderer.camera) {
            // Assuming 1920x1080 (1.77) is standard.
            // If aspect ratio is wider (e.g. Ultrawide or Fullscreen without sidebars), we should ZOOM OUT (decrease value) to fit more height
            // If aspect ratio is narrower (Mobile), we ZOOM OUT to fit width.

            // Actually, simply relying on map size vs screen size in CameraSystem handles bounds,
            // but the Director needs to know "What is a Close Up?".

            // For now, let's just create a dynamic modifier.
            // (In a real DOM implementation we'd need exact pixel width from the canvas via the engine, passing 1.0 for now)
            const aspectRatio = 1.77; // Default assumption
            this.idleZoom = 0.8;      // Pull back for better overview
            this.combatZoom = 1.1;
            this.ultZoom = 1.4;
        }

        const ds = engine.state.director;

        // 1. Timer Logic
        if (ds.priorityTimer > 0) ds.priorityTimer -= dt;
        if (ds.focusTimer > 0) ds.focusTimer -= dt;

        // 2. Select Target (Decision Making)
        this.decideTarget(engine, ds);

        // 3. Calculate Cinematic Frame (Computation)
        const frame = this.calculateFrame(engine, ds.targetId);

        // 4. Push to Camera System (Action)
        if (engine.renderer && frame) {
            engine.renderer.camera.setDirectorTarget(frame.x, frame.y, frame.zoom);
        }
    }

    private decideTarget(engine: GameEngine, ds: any) {
        if (ds.priorityTimer > 0) return;

        let needNewTarget = false;

        if (ds.targetId) {
            const current = engine.agents.find(a => a.id === ds.targetId);
            if (!current || current.hp <= 0 || current.banished) {
                needNewTarget = true;
            } else if (ds.focusTimer <= 0) {
                needNewTarget = true; 
            }
        } else {
            needNewTarget = true;
        }

        if (needNewTarget) {
            const bestCandidate = this.findBestCandidate(engine);
            if (bestCandidate) {
                if (ds.targetId !== bestCandidate.id) {
                    ds.targetId = bestCandidate.id;
                    const isAction = bestCandidate.castingSkillIdx !== -1;
                    ds.focusTimer = isAction ? 4.0 : 2.5;
                }
            } else {
                ds.targetId = null;
            }
        }
    }

    private findBestCandidate(engine: GameEngine): Agent | null {
        let candidates: Agent[] = [];
        let maxScore = -1;
        let best: Agent | null = null;

        for (const a of engine.agents) {
            if (a.hp <= 0 || a.banished) continue;

            let score = Math.random() * 10; 

            if (a.castingSkillIdx !== -1) {
                const skill = a.skills[a.castingSkillIdx];
                if (skill?.tag === 'ULT') score += 50; 
                else if (skill?.tag === 'ACTIVE') score += 20;
                else score += 5; 
            }
            if (a.hitFlashTimer > 0) score += 15; 
            if (a.isMoving) score += 5;

            if (a.role === 'WARRIOR' || a.role === 'TANK') score += 2;

            if (score > maxScore) {
                maxScore = score;
                best = a;
            }
        }
        return best;
    }

    private calculateFrame(engine: GameEngine, targetId: string | null): { x: number, y: number, zoom: number } | null {
        let targetX = 0;
        let targetY = 0;
        let targetZoom = this.idleZoom;

        const mainActor = targetId ? engine.agents.find(a => a.id === targetId) : null;

        if (mainActor && mainActor.hp > 0) {
            targetX = mainActor.px;
            targetY = mainActor.py;

            if (mainActor.target && mainActor.target.hp > 0) {
                const t = mainActor.target;
                targetX = mainActor.px * 0.6 + t.px * 0.4;
                targetY = mainActor.py * 0.6 + t.py * 0.4;

                const dist = HexUtils.dist(mainActor, t);
                if (dist < 2) targetZoom = this.combatZoom; 
                else if (dist < 6) targetZoom = (this.combatZoom + this.idleZoom) / 2;
                else targetZoom = this.idleZoom;

            } else if (mainActor.isMoving && mainActor.path.length > 0) {
                targetX += mainActor.physics.vx * 0.5; 
                targetY += mainActor.physics.vy * 0.5;
                targetZoom = this.idleZoom;
            } else {
                targetZoom = this.idleZoom * 1.1; 
            }

            if (mainActor.castingSkillIdx !== -1) {
                const skill = mainActor.skills[mainActor.castingSkillIdx];
                if (skill?.tag === 'ULT') {
                    targetX = mainActor.px;
                    targetY = mainActor.py - 20; 
                    targetZoom = this.ultZoom;
                }
            }

        } else {
            // Wide shot logic
            let sumX = 0, sumY = 0, count = 0;
            for (const a of engine.agents) {
                if (a.hp > 0) {
                    sumX += a.px;
                    sumY += a.py;
                    count++;
                }
            }

            if (count > 0) {
                targetX = sumX / count;
                targetY = sumY / count;
                // If battle is spread out, zoom out more
                // If map is large, zoom out more
                targetZoom = this.idleZoom * 0.9;
            } else {
                const centerHex = { q: Math.floor(engine.mapConfig.w/2), r: Math.floor(engine.mapConfig.h/2) };
                const centerPx = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);
                targetX = centerPx.x;
                targetY = centerPx.y;
                targetZoom = 0.75; // Maximum wide shot
            }
        }

        // Smoothing
        if (!this.hasInitialized) {
            this.lastCentroidX = targetX;
            this.lastCentroidY = targetY;
            this.hasInitialized = true;
        }

        this.lastCentroidX += (targetX - this.lastCentroidX) * 0.1;
        this.lastCentroidY += (targetY - this.lastCentroidY) * 0.1;

        return { x: targetX, y: targetY, zoom: targetZoom };
    }
}

