import { VFXSequence, VFXAction } from "../../types/VFXSchema";
import { DEFAULT_SKILL_DB } from "../../skillDatabase";
import { ULT_VISUALS } from "./ult_visuals";

const sequences: Record<string, VFXSequence> = {};

function fillFactionDefaults(prefix: string, primary: string, secondary: string, role: string) {
    const isRed = prefix.includes('r');
    const hitFx = `FX_HIT_${isRed ? 'RED' : 'BLUE'}_${role}`;

    for (let i = 1; i <= 5; i++) {
        // --- 1. BASIC SKILLS ---
        const basicId = `${prefix}_b${i}`;
        const basicSkill = DEFAULT_SKILL_DB.find(s => s.id === basicId);
        if (basicSkill) {
            const basicActions: VFXAction[] = [];
            // If instant hit (no projectile), show beam/slash
            if (!basicSkill.projectileSpeed || basicSkill.projectileSpeed <= 0) {
                const beamStyle = (role === 'WARRIOR' || role === 'TANK') ? 'SLASH_CONNECT' : 'GENERIC_BEAM';
                basicActions.push({ type: 'BEAM', style: beamStyle, color: basicSkill.color, duration: 0.15 });
            }
            // Always show impact
            const specificHit = basicSkill.visualHitEffect || hitFx;
            basicActions.push({ type: 'PARTICLE', id: specificHit, color: secondary, scale: 0.6, delay: 0.05 });
            basicActions.push({ type: 'SHAKE', shakeIntensity: 0.05, delay: 0.05 });
            sequences[basicId] = { id: basicId, actions: basicActions };
        }

        // --- 2. ACTIVE SKILLS ---
        const activeId = `${prefix}_a${i}`;
        const activeSkill = DEFAULT_SKILL_DB.find(s => s.id === activeId);
        if (activeSkill) {
            const specificHit = activeSkill.visualHitEffect || hitFx;
            sequences[activeId] = {
                id: activeId,
                actions: [
                    { type: 'PARTICLE', id: specificHit, color: secondary, scale: 0.8 },
                    { type: 'GRID_PULSE', color: primary, scale: 0.8, delay: 0.05 },
                    { type: 'SHAKE', shakeIntensity: 0.15 }
                ]
            };
        }

        // --- 3. ULTIMATE SKILLS (High Definition) ---
        const ultId = `${prefix}_u${i}`;
        const ultConfig = ULT_VISUALS[ultId];

        if (ultConfig) {
            const actions: VFXAction[] = [];

            switch (ultConfig.archetype) {
                case 'HEAVEN_FALL':
                    actions.push({ 
                        type: 'HEAVEN_FALL', 
                        style: 'METEOR', 
                        color: ultConfig.primaryColor, 
                        height: ultConfig.height || 1000, 
                        scale: ultConfig.scale 
                    });
                    actions.push({ 
                        type: 'PARTICLE', 
                        id: ultConfig.vfxOverride || `FX_ULT_${isRed?'RED':'BLUE'}_IMPACT`, 
                        scale: ultConfig.scale, 
                        delay: (ultConfig.timing || 0) + 0.4 
                    });
                    actions.push({ 
                        type: 'SHAKE', 
                        shakeIntensity: 0.8 * ultConfig.scale, 
                        delay: (ultConfig.timing || 0) + 0.4 
                    });
                    actions.push({
                        type: 'GRID_PULSE',
                        color: ultConfig.secondaryColor,
                        scale: ultConfig.scale * 2,
                        delay: (ultConfig.timing || 0) + 0.45
                    });
                    break;

                case 'SANCTUARY':
                    actions.push({
                        type: 'PARTICLE',
                        id: ultConfig.vfxOverride || 'PILLAR_HOLY',
                        scale: ultConfig.scale,
                        color: ultConfig.primaryColor
                    });
                    // Spawn ring of sub-particles
                    for(let k=0; k<(ultConfig.count || 6); k++) {
                        actions.push({
                            type: 'PARTICLE',
                            id: 'GLOW',
                            scale: 0.5,
                            color: ultConfig.secondaryColor,
                            delay: k * 0.05
                        });
                    }
                    actions.push({ type: 'GRID_PULSE', color: ultConfig.primaryColor, scale: 1.5, delay: 0.2 });
                    break;

                case 'DOMAIN':
                    actions.push({
                        type: 'PARTICLE',
                        id: ultConfig.vfxOverride || 'DOMAIN_STANDARD',
                        scale: ultConfig.scale,
                        color: ultConfig.primaryColor,
                        duration: 3.0
                    });
                    actions.push({
                        type: 'GRID_PULSE',
                        color: ultConfig.secondaryColor,
                        scale: ultConfig.scale * 1.5,
                        delay: 0.1
                    });
                    break;

                case 'BEAM_SNIPE':
                    actions.push({
                        type: 'BEAM',
                        style: ultConfig.vfxOverride || 'DEATH_RAY',
                        color: ultConfig.primaryColor,
                        duration: 0.8,
                        scale: ultConfig.scale
                    });
                    actions.push({
                        type: 'SHAKE',
                        shakeIntensity: 0.4,
                        delay: 0.1
                    });
                    actions.push({
                        type: 'PARTICLE',
                        id: 'SHOCKWAVE',
                        color: ultConfig.secondaryColor,
                        scale: 1.2
                    });
                    break;

                case 'STORM':
                    const count = ultConfig.count || 10;
                    const interval = ultConfig.timing || 0.1;
                    const fx = ultConfig.vfxOverride || 'SPARK';
                    for(let k=0; k<count; k++) {
                        actions.push({
                            type: 'PARTICLE',
                            id: fx,
                            color: k % 2 === 0 ? ultConfig.primaryColor : ultConfig.secondaryColor,
                            scale: ultConfig.scale * (0.8 + Math.random()*0.4),
                            delay: k * interval
                        });
                    }
                    break;

                case 'INSTANT_IMPACT':
                    actions.push({
                        type: 'PARTICLE',
                        id: ultConfig.vfxOverride || `FX_HIT_${isRed?'RED':'BLUE'}_HEAVY`,
                        scale: ultConfig.scale,
                        color: ultConfig.primaryColor
                    });
                    actions.push({
                        type: 'SHAKE',
                        shakeIntensity: 0.5 * ultConfig.scale,
                        delay: 0.05
                    });
                    actions.push({
                        type: 'GRID_PULSE',
                        color: ultConfig.secondaryColor,
                        scale: ultConfig.scale,
                        delay: 0.1
                    });
                    break;
            }

            sequences[ultId] = { id: ultId, actions };
        }
    }
}

